package com.sob.musicviz;

import java.util.Collections;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
class MidiScheduler
{
    private ScheduledExecutorService exec;
    private ScheduledFuture<?> task;

    private volatile List<NoteEvent> events = Collections.emptyList();
    private volatile long trackStartNanos = 0L;
    private volatile int cursor = 0;
    private volatile Consumer<NoteEvent> onNote = e -> {};

    @Inject
    MidiScheduler() {}

    synchronized void start(Consumer<NoteEvent> sink)
    {
        if (exec != null) return;
        this.onNote = sink;
        exec = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "musicviz-scheduler");
            t.setDaemon(true);
            return t;
        });
        task = exec.scheduleAtFixedRate(this::tick, 0, 5, TimeUnit.MILLISECONDS);
    }

    synchronized void stop()
    {
        if (task != null) { task.cancel(false); task = null; }
        if (exec != null) { exec.shutdownNow(); exec = null; }
        events = Collections.emptyList();
        cursor = 0;
    }

    synchronized void loadTrack(List<NoteEvent> noteEvents, long startNanos)
    {
        this.events = noteEvents;
        this.trackStartNanos = startNanos;
        this.cursor = 0;
        log.debug("loaded track: {} events", noteEvents.size());
    }

    private void tick()
    {
        try
        {
            List<NoteEvent> evs = events;
            if (evs.isEmpty()) return;

            long elapsedMs = (System.nanoTime() - trackStartNanos) / 1_000_000L;
            int i = cursor;
            while (i < evs.size() && evs.get(i).timestampMs <= elapsedMs)
            {
                try { onNote.accept(evs.get(i)); }
                catch (Throwable t) { log.warn("onNote sink threw", t); }
                i++;
            }
            cursor = i;
        }
        catch (Throwable t)
        {
            log.warn("scheduler tick threw", t);
        }
    }
}

package com.sob.musicviz;

import java.awt.Color;
import net.runelite.api.GameObject;

final class FlashState
{
    final GameObject target;
    final long startMs;
    final Color color;

    FlashState(GameObject target, long startMs, Color color)
    {
        this.target = target;
        this.startMs = startMs;
        this.color = color;
    }

    float progress(long nowMs, int decayMs)
    {
        long age = nowMs - startMs;
        if (age <= 0) return 0f;
        if (age >= decayMs) return 1f;
        return age / (float) decayMs;
    }

    boolean expired(long nowMs, int decayMs)
    {
        return nowMs - startMs >= decayMs;
    }
}

package com.sob.musicviz;

import com.google.inject.Provides;
import java.util.List;
import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.MidiRequest;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Music Visualizer",
    description = "Flashes nearby objects on the notes of the current music track.",
    tags = {"music", "visualizer", "overlay", "midi"}
)
public class MusicVizPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private MusicVizConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private MusicVizOverlay overlay;
    @Inject private MidiScheduler scheduler;
    @Inject private ObjectScanner scanner;
    @Inject private FlashStore flashes;
    @Inject private MidiCacheLoader cacheLoader;

    private ScheduledExecutorService pollExec;
    private ScheduledFuture<?> pollTask;
    private volatile int lastArchiveId = Integer.MIN_VALUE;
    private final Random rr = new Random();
    private int rrCursor = 0;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        scheduler.start(this::onNote);
        startPolling();
    }

    @Override
    protected void shutDown()
    {
        stopPolling();
        scheduler.stop();
        overlayManager.remove(overlay);
        flashes.clear();
        lastArchiveId = Integer.MIN_VALUE;
    }

    @Provides
    MusicVizConfig provideConfig(ConfigManager cm)
    {
        return cm.getConfig(MusicVizConfig.class);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged ev)
    {
        // Currently no-op — scheduler holds its own clock. We may want to
        // clear flashes on logout so they don't linger on the login screen.
    }

    @Subscribe
    public void onGameTick(GameTick ev)
    {
        scanner.refresh(config.radius());
    }

    private void startPolling()
    {
        pollExec = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "musicviz-trackpoll");
            t.setDaemon(true);
            return t;
        });
        pollTask = pollExec.scheduleAtFixedRate(
            () -> clientThread.invoke(this::pollActiveTrack),
            500, config.pollIntervalMs(), TimeUnit.MILLISECONDS);
    }

    private void stopPolling()
    {
        if (pollTask != null) { pollTask.cancel(false); pollTask = null; }
        if (pollExec != null) { pollExec.shutdownNow(); pollExec = null; }
    }

    /**
     * Runs on client thread. Detects active-track change by reference
     * identity of the first MidiRequest. On change, kicks off off-thread
     * load + parse so we don't stall the client.
     */
    private void pollActiveTrack()
    {
        try
        {
            List<MidiRequest> active = client.getActiveMidiRequests();
            if (active == null || active.isEmpty())
            {
                if (lastArchiveId != Integer.MIN_VALUE)
                {
                    lastArchiveId = Integer.MIN_VALUE;
                    scheduler.loadTrack(java.util.Collections.emptyList(), System.nanoTime());
                }
                return;
            }
            MidiRequest req = active.get(0);
            int archiveId = req.getArchiveId();
            boolean jingle = req.isJingle();
            if (archiveId == lastArchiveId) return;
            lastArchiveId = archiveId;
            long startNanos = System.nanoTime() - TimeUnit.MILLISECONDS.toNanos(config.syncOffsetMs());
            // Cache read is fast (in-memory in the running client) so we do it on
            // the client thread; only the SMF conversion + note flattening get
            // pushed off-thread.
            byte[] cacheBytes = cacheLoader.load(archiveId, jingle);
            parseAsync(archiveId, cacheBytes, startNanos);
        }
        catch (Throwable t)
        {
            log.debug("pollActiveTrack failed", t);
        }
    }

    private void parseAsync(int archiveId, byte[] cacheBytes, long startNanos)
    {
        if (pollExec == null) return;
        if (cacheBytes == null)
        {
            if (config.logCacheMisses())
            {
                log.info("musicviz: no cache bytes for archive {} — idle", archiveId);
            }
            scheduler.loadTrack(java.util.Collections.emptyList(), startNanos);
            return;
        }
        pollExec.submit(() -> {
            try
            {
                List<NoteEvent> events = MidiTrackResolver.flatten(cacheBytes);
                log.debug("musicviz: parsed {} note events from archive {}", events.size(), archiveId);
                scheduler.loadTrack(events, startNanos);
                flashes.clear();
            }
            catch (Throwable t)
            {
                log.warn("musicviz: failed to parse MIDI for archive {}", archiveId, t);
            }
        });
    }

    private void onNote(NoteEvent ev)
    {
        int wantedChannel = config.melodyChannel();
        if (wantedChannel >= 0 && ev.channel != wantedChannel) return;
        List<GameObject> targets = scanner.get();
        if (targets.isEmpty()) return;

        int idx;
        switch (config.selectionMode())
        {
            case HASH_BY_NOTE:
                idx = (int) Math.floorMod((long) ev.note * 2654435761L, targets.size());
                break;
            case ROUND_ROBIN:
                idx = Math.floorMod(rrCursor++, targets.size());
                break;
            case RANDOM:
            default:
                idx = rr.nextInt(targets.size());
                break;
        }
        GameObject target = targets.get(idx);
        flashes.add(new FlashState(target, System.currentTimeMillis(), NoteColor.forNote(ev.note)));
    }
}

package com.sob.musicviz;

import java.util.Iterator;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.Consumer;
import javax.inject.Singleton;

@Singleton
class FlashStore
{
    private final ConcurrentLinkedQueue<FlashState> active = new ConcurrentLinkedQueue<>();

    void add(FlashState flash)
    {
        active.add(flash);
    }

    void clear()
    {
        active.clear();
    }

    void forEachActive(long nowMs, int decayMs, Consumer<FlashState> visitor)
    {
        Iterator<FlashState> it = active.iterator();
        while (it.hasNext())
        {
            FlashState f = it.next();
            if (f.expired(nowMs, decayMs))
            {
                it.remove();
                continue;
            }
            visitor.accept(f);
        }
    }
}

package com.sob.musicviz;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;

/**
 * Reads raw OSRS music bytes by archive id, using the running RuneLite client's
 * own cache accessor (Client.getIndex). The bytes returned are in Jagex's
 * packed format and must be passed through {@link com.sob.musicviz.vendored.TrackLoader}
 * to be converted into standard SMF.
 *
 * Index numbers come from the OSRS cache layout: 6 = music tracks, 11 = jingles.
 */
@Slf4j
@Singleton
final class MidiCacheLoader
{
    private static final int INDEX_MUSIC_TRACKS = 6;
    private static final int INDEX_MUSIC_JINGLES = 11;

    private final Client client;

    @Inject
    MidiCacheLoader(Client client)
    {
        this.client = client;
    }

    byte[] load(int archiveId, boolean jingle)
    {
        try
        {
            int indexId = jingle ? INDEX_MUSIC_JINGLES : INDEX_MUSIC_TRACKS;
            IndexDataBase index = client.getIndex(indexId);
            if (index == null)
            {
                log.warn("musicviz: client returned null for index {}", indexId);
                return null;
            }
            byte[] bytes = index.loadData(archiveId, 0);
            if (bytes == null || bytes.length == 0)
            {
                log.debug("musicviz: index {} archive {} returned no bytes", indexId, archiveId);
                return null;
            }
            return bytes;
        }
        catch (Throwable t)
        {
            log.warn("musicviz: failed to load archive {} (jingle={})", archiveId, jingle, t);
            return null;
        }
    }
}

package com.sob.musicviz;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;

@Singleton
class ObjectScanner
{
    private final Client client;

    private volatile List<GameObject> snapshot = Collections.emptyList();

    @Inject
    ObjectScanner(Client client)
    {
        this.client = client;
    }

    void refresh(int radius)
    {
        Player local = client.getLocalPlayer();
        if (local == null)
        {
            snapshot = Collections.emptyList();
            return;
        }

        LocalPoint playerLoc = local.getLocalLocation();
        Scene scene = client.getScene();
        Tile[][][] tiles = scene.getTiles();
        int plane = client.getPlane();
        Tile[][] planeTiles = tiles[plane];

        int radiusUnits = radius * 128;
        long radSq = (long) radiusUnits * radiusUnits;

        List<GameObject> found = new ArrayList<>();
        for (int sx = 0; sx < planeTiles.length; sx++)
        {
            Tile[] row = planeTiles[sx];
            for (int sy = 0; sy < row.length; sy++)
            {
                Tile tile = row[sy];
                if (tile == null) continue;

                GameObject[] objs = tile.getGameObjects();
                if (objs == null) continue;

                for (GameObject obj : objs)
                {
                    if (obj == null) continue;
                    LocalPoint p = obj.getLocalLocation();
                    if (p == null) continue;
                    long dx = p.getX() - playerLoc.getX();
                    long dy = p.getY() - playerLoc.getY();
                    if (dx * dx + dy * dy > radSq) continue;
                    found.add(obj);
                }
            }
        }

        snapshot = found;
    }

    List<GameObject> get()
    {
        return snapshot;
    }
}
